from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import VersionURI


class VersionV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_nadcm_versions_info(self, timeout=60):
        uri = VersionURI().version_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)
